pragma solidity 0.8.24;

import "@openzeppelin/contracts-upgradeable/interfaces/IERC721EnumerableUpgradeable.sol";


interface IPlayFiLicense is IERC721EnumerableUpgradeable
{
    event LicenseMinted(address indexed receiver,uint256 indexed tokenId);

    error AccessDenied();
    error UnexistingToken(uint256 tokenId);
    error InvalidAddress(address account);
    error TransferNotAllowed(address from, address to, uint256 firstTokenId);

    function mint(address receiver, uint256 amount) external;
    function currentLicenseId() external view returns (uint256);
}
","keccak256":"0x6db6994346385dbc3a6743b3e13f3b57cc9a16c2a28d05499d8800b8f7af2b7f","license":"MIT"},"contracts/interfaces/IPlayFiLicenseMint.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IPlayFiLicense} from "./IPlayFiLicense.sol";


interface IPlayFiLicenseMint
{
    event Paused(bool status);
    event MintMerkleRootSet(bytes32 merkleRoot);
    event LicensesMinted(address indexed originalBuyer, address indexed minter, uint256 amount);
    event ContractInitialized();

    error MintCapExceeded();
    error ContractPaused();
    error InvalidProof();
    error InvalidSignature();
    error AccessDenied();
    error InvalidAddress(address account);

    function mintLicenses(address claimAddress, bytes calldata claimData, uint256 amount, bytes32[] calldata merkleProof, bytes calldata signature) external;
    function setMintMerkleRoot(bytes32 _mintMerkleRoot) external;
    function setPaused(bool status) external;
    function mintMerkleRoot() external view returns (bytes32);
    function paused() external view returns (bool);
    function playFiLicense() external view returns (IPlayFiLicense playFiLicense);

}
